  `lotno` varchar(50) DEFAULT NULL,
  `prod_order` varchar(50) DEFAULT NULL,
  `shift` varchar(2) DEFAULT NULL,
  `start_date` datetime DEFAULT NULL,
  `counter_filling` int DEFAULT NULL COMMENT 'Dari cttn_prod_area_filling',
  `prev_pro` varchar(50) DEFAULT NULL COMMENT 'PRO sebelumnya',
  `finish_prev_pro` datetime DEFAULT NULL COMMENT 'Auto fill dari field prev_lot',
  `start_filling` datetime DEFAULT NULL COMMENT 'Dari mst_prodidentity untuk start lot',
  `start_shift` datetime DEFAULT NULL COMMENT 'Start shift',
  `finish_filling` datetime DEFAULT NULL COMMENT 'Inputan user',
  `fg_teori` int DEFAULT NULL,
  `delay` int DEFAULT NULL COMMENT 'Minutes',
  `fg` int DEFAULT NULL,
  `fg_teori_detail_scheduler` int DEFAULT NULL,
  `line_eff` double(5,2) DEFAULT NULL,
  `preform_to_blow` int DEFAULT NULL COMMENT 'Inputan',
  `change_lot_pro` int DEFAULT NULL COMMENT 'Minutes (Input)',
  `scheduler_downtime` int DEFAULT NULL COMMENT 'SUM menit dari tr_abnormalitas untuk yang DS* TIMESTAMPDIFF(MINUTE,a.start_time, a.end_time)',
  `capacity_time` int DEFAULT NULL COMMENT 'jam inputan finish filling - finish lot sebelumnya (menit)',
  `production_time` int DEFAULT NULL,
  `breakdown` int DEFAULT NULL COMMENT 'tr_abnormalitas WHERE isDowntime = ''downtime'' AND reason_code NOT LIKE ''DS%'' AND selisih >= 5menit',
  `operating_time` int DEFAULT NULL,
  `net_operating_time` int DEFAULT NULL,
  `rejection` int DEFAULT NULL,
  `minor_stoppage` int DEFAULT NULL COMMENT 'tr_abnormalitas WHERE isDowntime = ''downtime'' AND reason_code NOT LIKE ''DS%'' AND selisih < 5menit',
  `loss_time` int DEFAULT NULL COMMENT 'Harus bernilai 0 ',
  `availability` double(5,2) DEFAULT NULL,
  `performance` double(5,2) DEFAULT NULL,
  `quality` double(5,2) DEFAULT NULL,
  `oee` double(5,2) DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `pic` varchar(100) DEFAULT NULL,
  `index_report` int DEFAULT NULL COMMENT 'Marking report untuk ditampilkan di grafana',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1858 DEFAULT CHARSET=latin1;
